'use strict';
const q=s=>document.querySelector(s),qa=s=>[...document.querySelectorAll(s)];
const menu=q('#menu-toggle');if(menu)menu.addEventListener('click',()=>{const open=q('#navigation').classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');});
if(q('#find-journeys')){const filter=()=>{const interest=q('#journey-interest').value,length=q('#journey-length').value;let n=0;qa('#journey-results .journey-card').forEach(card=>{const days=Number(card.dataset.days),match=(interest==='all'||card.dataset.category===interest)&&(length==='all'||length==='short'&&days<=7||length==='medium'&&days>=8&&days<=12||length==='long'&&days>=13);card.hidden=!match;if(match)n++;});q('#journey-count').textContent=`${n} suggested ${n===1?'journey':'journeys'}`;q('#no-journeys').hidden=n!==0;};q('#find-journeys').addEventListener('click',filter);}
if(q('#cruise-summary')){const update=()=>{const direction=q('#cruise-direction'),style=q('#cruise-style').value,duration=q('#cruise-duration').value,label=direction.options[direction.selectedIndex].text;q('#cruise-summary').textContent=`${label} · ${style} · ${duration}`;const params=new URLSearchParams({type:'cruise',direction:label,style,duration});q('.preference-summary .button').href='/plan-my-trip/?'+params;};qa('.cruise-tool select').forEach(el=>el.addEventListener('change',update));update();}
if(q('#planning-form')){
 const form=q('#planning-form'),params=new URLSearchParams(location.search);let type='private',step=1;
 const setStep=n=>{step=n;q('#step-one').hidden=n!==1;q('#step-two').hidden=n!==2;q('#step-one').disabled=n!==1;q('#step-two').disabled=n!==2;q('#step-label').textContent=n===1?'STEP 1 OF 2 · YOUR IDEAS':'STEP 2 OF 2 · YOUR PREFERENCES';q('#step-progress').style.width=n===1?'50%':'100%';};
 const setType=t=>{type=['private','rail','cruise'].includes(t)?t:'private';qa('[data-type]').forEach(b=>{b.classList.toggle('active',b.dataset.type===type);b.setAttribute('aria-pressed',String(b.dataset.type===type));});qa('.type-fields').forEach(group=>{const active=group.id===type+'-fields';group.hidden=!active;group.querySelectorAll('input,select').forEach(el=>el.disabled=!active);});q('#form-heading').textContent={private:'What does your China look like?',rail:'Let’s shape your rail journey.',cruise:'Find the river journey for you.'}[type];form.hidden=false;q('#inquiry-result').hidden=true;setStep(1);};
 qa('[data-type]').forEach(b=>b.addEventListener('click',()=>setType(b.dataset.type)));setType(params.get('type'));
 if(params.has('journey'))form.elements.destination.value=params.get('journey').replaceAll('-',' ');if(params.has('destination'))form.elements.destination.value=params.get('destination');
 if(params.has('interest')){const requested=params.get('interest');const option=[...form.elements.interest.options].find(o=>o.value.includes(requested));if(option)form.elements.interest.value=option.value;}
 for(const [param,field] of [['direction','cruiseDirection'],['style','cruiseStyle'],['duration','cruiseDuration']]){const value=params.get(param);if(value&&[...form.elements[field].options].some(o=>o.value===value))form.elements[field].value=value;}
 q('#next-step').addEventListener('click',()=>{if(form.reportValidity()){setStep(2);q('#form-heading').closest('form').scrollIntoView({behavior:'smooth',block:'start'});q('#step-two select').focus({preventScroll:true});}});
 q('#previous-step').addEventListener('click',()=>setStep(1));
 form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const value=name=>form.elements[name]?.value.trim()||'To discuss';let lines=[{private:'PRIVATE JOURNEY',rail:'LUXURY RAIL JOURNEY',cruise:'YANGTZE CRUISE'}[type],''];
 if(type==='private')lines.push('Interest: '+value('interest'),'Destination / journey: '+value('destination'));
 if(type==='rail')lines.push('Departure area: '+value('railRoute'),'Cabin preference: '+value('railCabin'),'Private extensions: '+value('railExtension'));
 if(type==='cruise')lines.push('Direction: '+value('cruiseDirection'),'Cruise style: '+value('cruiseStyle'),'Cruise duration: '+value('cruiseDuration'),'Cabin preference: '+value('cruiseCabin'),'Transfers / extensions: '+value('cruiseExtension'));
 const fields=[['date','Preferred date'],['flexibility','Date flexibility'],['adults','Adults'],['children','Children'],['ages','Children’s ages'],['days','Total journey days'],['budget','Budget per person (excluding international flights)'],['hotel','Hotel preference'],['pace','Travel pace'],['name','Name'],['email','Email'],['country','Country / region'],['whatsapp','WhatsApp'],['notes','Additional ideas']];fields.forEach(([name,label])=>lines.push(label+': '+value(name)));lines.push('','PREVIEW ONLY — NOT SENT. No inquiry or booking has been created.');q('#inquiry-summary').textContent=lines.join('\n');form.hidden=true;q('#inquiry-result').hidden=false;q('#inquiry-result').focus();q('#inquiry-result').scrollIntoView({behavior:'smooth',block:'start'});
 });
 q('#edit-inquiry').addEventListener('click',()=>{q('#inquiry-result').hidden=true;form.hidden=false;setStep(2);});
 q('#copy-inquiry').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(q('#inquiry-summary').textContent);q('#copy-status').textContent='Summary copied. It has not been sent.';}catch{q('#copy-status').textContent='Please select the summary text and copy it manually.';}});
}
